/* Build src/content/videoIndex.generated.js from creatorVideos.txt.
 *
 * WHY A SEPARATE GENERATED FILE, NOT A SECOND READER OF creatorVideos.txt.
 * creatorVideos.js reads the flat file with Vite's `?raw` import — a Vite-only
 * convention. functions/_middleware.js is a Cloudflare Pages FUNCTION, built by
 * Wrangler's own bundler, which has never heard of `?raw`. Rather than teach
 * two bundlers to agree, this writes a plain ES module of object literals that
 * either one can import with zero special config — the same trick
 * creatorVideosFallback.js already uses for its own generated data.
 *
 * WHAT IT'S FOR. /v/<id> (a page per roster video, so Google can index more
 * than the one-per-page it otherwise picks) and sitemap-videos.xml both need
 * to answer, at the edge and without a network call, "is this id one of
 * ours, and whose?" Dates and descriptions are deliberately left out — they
 * are not in creatorVideos.txt either (see its own header), and fetching them
 * per video would be one more point of failure for something sitemap/page
 * generation does not need to be exact.
 *
 * SLUGS stored once and referenced by index, not repeated per video — at
 * several thousand rows that is the difference between this file being
 * tens of kilobytes and being megabytes.
 *
 * Run it:  npm run videoindex:build   (after npm run creators:fetch)
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const CACHE = join(__dirname, '../src/content/creatorVideos.txt');
const OUT = join(__dirname, '../src/content/videoIndex.generated.js');

const YT_ID = /^[A-Za-z0-9_-]{11}$/;

function parse(raw) {
  const slugs = [];
  const slugIndex = new Map();
  const videos = new Map(); // id -> [slugIdx, title]  (first writer wins — see below)
  for (const line of String(raw || '').split('\n')) {
    const text = line.trim();
    if (!text || text.startsWith('#')) continue;
    const parts = text.split('|');
    if (parts.length < 3) continue;
    const slug = parts[0].trim();
    const id = parts[1].trim();
    const title = parts.slice(2).join('|').trim();
    if (!slug || !YT_ID.test(id) || !title) continue;

    if (!slugIndex.has(slug)) { slugIndex.set(slug, slugs.length); slugs.push(slug); }
    // The same id should never appear under two slugs, but if the cache is ever
    // hand-edited into that state, keep the first mapping rather than flapping
    // between two creators on every rebuild.
    if (!videos.has(id)) videos.set(id, [slugIndex.get(slug), title]);
  }
  return { slugs, videos };
}

const { slugs, videos } = parse(readFileSync(CACHE, 'utf8'));

if (videos.size === 0) {
  console.error(`No videos parsed from ${CACHE} — is it still empty? Run npm run creators:fetch -- all first.`);
  process.exit(1);
}

const esc = (s) => JSON.stringify(s);
const lines = [...videos.entries()].map(([id, [slugIdx, title]]) => `  ${esc(id)}: [${slugIdx}, ${esc(title)}],`);

const body = `/* AUTO-GENERATED by scripts/build-video-index.mjs from creatorVideos.txt.
 * Do not hand-edit — re-run the generator instead. See that script for why
 * this exists as its own plain-ESM file rather than a second reader of the
 * flat file.
 *
 * SLUGS[i] names a roster creator (content/creators.js). VIDEOS[id] is
 * [slugIndex, title] for every cached video across every creator.
 */
export const SLUGS = ${JSON.stringify(slugs)};

export const VIDEOS = {
${lines.join('\n')}
};
`;

writeFileSync(OUT, body);
console.log(`Wrote ${OUT}: ${videos.size} videos across ${slugs.length} creators.`);
